fn is_odd_at_index_odd(a: &Vec<i32>) -> bool {
    // For every odd index i (1, 3, 5, ...), check that a[i] is not divisible by 2.
    // If we find any even element at an odd index, return false.
    for (i, &value) in a.iter().enumerate() {
        if i % 2 == 1 && value % 2 == 0 {
            return false;
        }
    }
    // If no counterexample was found, return true.
    true
}

